/* @lc app=leetcode id=2608 lang=kotlin */
class Solution { fun findShortestCycle(n: Int, edges: Array<IntArray>): Int = (Array(n) { mutableListOf<Int>() }.also { adj -> edges.forEach { e -> adj[e[0]].add(e[1]).also { adj[e[1]].add(e[0]) } } }).let { adj -> (0 until n).map { start -> IntArray(n) { -1 }.let { dist -> IntArray(n) { -1 }.let { parent -> java.util.ArrayDeque<Int>().also { q -> q.add(start).also { dist[start] = 0 } }.let { q -> generateSequence { q.poll() }.fold(1000000) { minC, u -> adj[u].fold(minC) { acc, v -> if (dist[v] == -1) (dist[u] + 1).let { d -> dist[v] = d.also { parent[v] = u.also { q.add(v) } }.run { acc } } else if (v != parent[u]) minOf(acc, dist[u] + dist[v] + 1) else acc } } } } } }.minOf { it }.let { if (it >= 1000000) -1 else it } } }